/*

Name:   catena-message-port3-port6-decoder-ttn.js

Function:
    Decode MCCI port 0x03/0x06 messages for TTN console.

Copyright and License:
    See accompanying LICENSE file at https://github.com/mcci-catena/MCCI-Catena-PMS7003/

Author:
    Terry Moore, MCCI Corporation   July 2019

*/

// calculate dewpoint (degrees C) given temperature (C) and relative humidity (0..100)
// from http://andrew.rsmas.miami.edu/bmcnoldy/Humidity.html
// rearranged for efficiency and to deal sanely with very low (< 1%) RH
function dewpoint(t, rh) {
    var c1 = 243.04;
    var c2 = 17.625;
    var h = rh / 100;
    if (h <= 0.01)
        h = 0.01;
    else if (h > 1.0)
        h = 1.0;

    var lnh = Math.log(h);
    var tpc1 = t + c1;
    var txc2 = t * c2;
    var txc2_tpc1 = txc2 / tpc1;

    var tdew = c1 * (lnh + txc2_tpc1) / (c2 - lnh - txc2_tpc1);
    return tdew;
}

/*

Name:   CalculateHeatIndex()

Description:
        Calculate the NWS heat index given dry-bulb T and RH

Definition:
        function CalculateHeatIndex(t, rh) -> value or null

Description:
        T is a Farentheit temperature in [76,120]; rh is a
        relative humidity in [0,100]. The heat index is computed
        and returned; or an error is returned.

Returns:
        number => heat index in Farenheit.
        null => error.

References:
        https://github.com/mcci-catena/heat-index/
        https://www.wpc.ncep.noaa.gov/html/heatindex_equation.shtml

        Results was checked against the full chart at iweathernet.com:
        https://www.iweathernet.com/wxnetcms/wp-content/uploads/2015/07/heat-index-chart-relative-humidity-2.png

        The MCCI-Catena heat-index site has a test js script to generate CSV to
        match the chart, a spreadsheet that recreates the chart, and a
        spreadsheet that compares results.

*/

function CalculateHeatIndex(t, rh) {
    var tRounded = Math.floor(t + 0.5);

    // return null outside the specified range of input parameters
    if (tRounded < 76 || tRounded > 126)
        return null;
    if (rh < 0 || rh > 100)
        return null;

    // according to the NWS, we try this first, and use it if we can
    var tHeatEasy = 0.5 * (t + 61.0 + ((t - 68.0) * 1.2) + (rh * 0.094));

    // The NWS says we use tHeatEasy if (tHeatHeasy + t)/2 < 80.0
    // This is the same computation:
    if ((tHeatEasy + t) < 160.0)
            return tHeatEasy;

    // need to use the hard form, and possibly adjust.
    var t2 = t * t;         // t squared
    var rh2 = rh * rh;      // rh squared
    var tResult =
        -42.379 +
        (2.04901523 * t) +
        (10.14333127 * rh) +
        (-0.22475541 * t * rh) +
        (-0.00683783 * t2) +
        (-0.05481717 * rh2) +
        (0.00122874 * t2 * rh) +
        (0.00085282 * t * rh2) +
        (-0.00000199 * t2 * rh2);

    // these adjustments come from the NWA page, and are needed to
    // match the reference table.
    var tAdjust;
    if (rh < 13.0 && 80.0 <= t && t <= 112.0)
        tAdjust = -((13.0 - rh) / 4.0) * Math.sqrt((17.0 - Math.abs(t - 95.0)) / 17.0);
    else if (rh > 85.0 && 80.0 <= t && t <= 87.0)
        tAdjust = ((rh - 85.0) / 10.0) * ((87.0 - t) / 5.0);
    else
        tAdjust = 0;

    // apply the adjustment
    tResult += tAdjust;

    // finally, the reference tables have no data above 183 (rounded),
    // so filter out answers that we have no way to vouch for.
    if (tResult >= 183.5)
        return null;
    else
        return tResult;
}

function CalculateHeatIndexCelsius(t, rh) {
    var result = CalculateHeatIndex(t, rh);
    if (result !== null) {
        // convert to celsius.
        result = (result - 32) * 5 / 9;
    }
    return result;
}

/*

Name:  Decoder()

Function:
    Decode an MCCI Catena port-3/6 message for The Things Network console.

Definition:
    function Decoder(bytes, port) -> object

Description:
    This function decodes the message given by the byte array `bytes[]`,
    and returns an object with values in engineering units.

Returns:
    Object, or null if the bytes could not be decoded.

*/

function Decoder(bytes, port) {
    // Decode an uplink message from a buffer
    // (array) of bytes to an object of fields.
    var decoded = {};

    if (! (port === 3)  && ! (port === 6))
        return null;

    // see catena-message-port3-format.md
    // i is used as the index into the message. Start with the flag byte.
    // note that there's no discriminator.
    // test vectors are also available there.
    var i = 0;
    // fetch the bitmap.
    var flags = bytes[i++];

    if (flags & 0x1) {
        // set Vraw to a uint16, and increment pointer
        var Vraw = (bytes[i] << 8) + bytes[i + 1];
        i += 2;
        // interpret uint16 as an int16 instead.
        if (Vraw & 0x8000)
            Vraw += -0x10000;
        // scale and save in result.
        decoded.Vbat = Vraw / 4096.0;
    }

    if (flags & 0x2) {
        var Vraw = (bytes[i] << 8) + bytes[i + 1];
        i += 2;
        if (Vraw & 0x8000)
            Vraw += -0x10000;
        decoded.VDD = Vraw / 4096.0;
    }

    if (flags & 0x4) {
        var iBoot = bytes[i];
        i += 1;
        decoded.boot = iBoot;
    }

    if (flags & 0x8) {
        // we have temp, pressure, RH
        var tRaw = (bytes[i] << 8) + bytes[i + 1];
        if (tRaw & 0x8000)
            tRaw = -0x10000 + tRaw;
        i += 2;
        var rhRaw = (bytes[i] << 8) + bytes[i + 1];
        i += 2;

        decoded.t = tRaw / 256;
        decoded.rh = rhRaw / 65535.0 * 100;
        decoded.tDew =  dewpoint(decoded.t, decoded.rh);
        decoded.tHeatIndexC = CalculateHeatIndexCelsius(decoded.t, decoded.rh);
    }

    if (flags & 0x10) {
        if (port === 3)
            {
            // we have light irradiance info
            var irradiance = {};
            decoded.irradiance = irradiance;

            var lightRaw = (bytes[i] << 8) + bytes[i + 1];
            i += 2;
            irradiance.IR = lightRaw;

            lightRaw = (bytes[i] << 8) + bytes[i + 1];
            i += 2;
            irradiance.White = lightRaw;

            lightRaw = (bytes[i] << 8) + bytes[i + 1];
            i += 2;
            irradiance.UV = lightRaw;
            }

        else if (port === 6)
            {
            // we have light (lux)
            var luxRaw = (bytes[i] << 16) + (bytes[i + 1] << 8) + bytes[i + 2];
            i = i + 3;

            // luxRaw is the 3-byte number decoded from wherever;
            // it's in range 0..0xFFFFFF
            // bit 23 is the sign bit
            // bits 22..16 are the exponent
            // bits 15..0 are the the mantissa. Unlike IEEE format,
            // the msb is explicit; this means that numbers
            // might not be normalized, but makes coding for
            // underflow easier.
            // As with IEEE format, negative zero is possible, so
            // we special-case that in hopes that JavaScript will
            // also cooperate.

            // extract sign, exponent, mantissa
            var bSign     = (luxRaw & 0x800000) ? true : false;
            var uExp      = (luxRaw & 0x7F0000) >> 16;
            var uMantissa = (luxRaw & 0x00FFFF);

            // if non-numeric, return appropriate result.
            if (uExp === 0x7F) {
                if (uMantissa === 0)
                    return bSign ? Number.NEGATIVE_INFINITY
                            : Number.POSITIVE_INFINITY;
                else
                    return Number.NaN;
            // else unless denormal, set the 1.0 bit
            } else if (uExp !== 0) {
                uMantissa += 0x010000;
            } else { // denormal: exponent is the minimum
                uExp = 1;
            }

            // make a floating mantissa in [0,2); usually [1,2), but
            // sometimes (0,1) for denormals, and exactly zero for zero.
            var mantissa = uMantissa / 0x010000;

            // apply the exponent.
            mantissa = Math.pow(2, uExp - 63) * mantissa;

            // apply sign and return result.
            decoded.lux = bSign ? -mantissa : mantissa;
            }
    }

    if (flags & 0x20) {
        var Vraw = (bytes[i] << 8) + bytes[i + 1];
        i += 2;
        if (Vraw & 0x8000)
            Vraw += -0x10000;
        decoded.Vbus = Vraw / 4096.0;
    }

    // at this point, decoded has the real values.
    return decoded;
}
// end catnea-message-port3-port6-decoder-ttn.js

/*

Node-RED function body.

Input:
    msg     the object to be decoded.

            msg.payload_raw is taken
            as the raw payload if present; otheriwse msg.payload
            is taken to be a raw payload.

            msg.port is taken to be the LoRaWAN port nubmer.


Returns:
    This function returns a message body. It's a mutation of the
    input msg; msg.payload is changed to the decoded data, and
    msg.local is set to additional application-specific information.

*/

var b;

if ("payload_raw" in msg) {
    // the console already decoded this
    b = msg.payload_raw;  // pick up data for convenience
    // msg.payload_fields still has the decoded data
}
else {
    // no console debug
    b = msg.payload;  // pick up data for conveneince
}

var result = Decoder(b, msg.port);

// now update msg with the new payload and new .local field
// the old msg.payload is overwritten.
msg.payload = result;
msg.local =
    {
        nodeType: "Catena 4617/4618",
        platformType: "Catena 461x",
        radioType: "Murata",
        applicationName: "Simple sensor"
    };

return msg;

// -------------------- SAFETY CHECKS --------------------
if (!msg.payload || typeof msg.payload !== "object") {
    return null;
}

// -------------------- BUILD METADATA --------------------
var metadata;

if (msg.metadata) {
    // TTN path
    metadata = msg.metadata;
} 
else if (msg.payload.txInfo && msg.payload.rxInfo) {
    // ChirpStack path
    metadata = {
        frequency: msg.payload.txInfo.frequency / 1e6,
        data_rate: "SF" + msg.payload.txInfo.modulation.lora.spreadingFactor +
                   "BW" + (msg.payload.txInfo.modulation.lora.bandwidth / 1000),
        coding_rate: msg.payload.txInfo.modulation.lora.codeRate,
        gateways: (msg.payload.rxInfo || []).map(gw => ({
            rssi: gw.rssi,
            snr: gw.snr,
            channel: gw.channel,
            gtw_id: gw.gatewayId
        }))
    };
} 
else {
    // Not an uplink message → ignore
    return null;
}

// -------------------- DATA RATE PARSE --------------------
var data_rate_re = /SF(\d+)BW(\d+)/;
var dataRateArray = data_rate_re.exec(metadata.data_rate);

if (!dataRateArray) {
    return null;
}

// -------------------- BEST GATEWAY --------------------
function findBestGateway(g) {
    var rssi = -1000;
    var bestRssi;
    var snr = -1000;
    var bestSnr;

    for (var i in g) {
        if (g[i].rssi > rssi) {
            rssi = g[i].rssi;
            bestRssi = i;
        }
        if (g[i].snr > snr) {
            snr = g[i].snr;
            bestSnr = i;
        }
    }

    if (bestRssi == bestSnr)
        return g[bestRssi];

    if (rssi < -80)
        return g[bestSnr];
    else
        return g[bestRssi];
}

var g = findBestGateway(metadata.gateways || []);

if (!g) {
    return null;
}

// -------------------- DEVICE INFO --------------------
var devEUI = msg.hardware_serial || (msg.payload.deviceInfo && msg.payload.deviceInfo.devEui);
var devID  = msg.dev_id || (msg.payload.deviceInfo && msg.payload.deviceInfo.deviceName);
var counter = msg.counter || msg.payload.fCnt;

// -------------------- RESULT --------------------
var result = {
    payload: [
        {
            frequency: metadata.frequency,
            channel: g.channel,
            datarate: metadata.data_rate,
            codingrate: metadata.coding_rate,
            spreadingFactor: Number(dataRateArray[1]),
            bandwidth: Number(dataRateArray[2]),
            rssi: g.rssi,
            snr: g.snr,
            msgID: msg._msgid,
            counter: counter,
        },
        {
            devEUI: devEUI,
            devID: devID,
            gatewayEUI: g.gtw_id,
            nodeType: msg.local && msg.local.nodeType,
            platformType: msg.local && msg.local.platformType,
            radioType: msg.local && msg.local.radioType,
            applicationName: msg.local && msg.local.applicationName,
            frequency: metadata.frequency,
            channel: g.channel,
            datarate: metadata.data_rate,
            spreadingFactor: Number(dataRateArray[1]),
            bandwidth: Number(dataRateArray[2]),
            codingrate: metadata.coding_rate,
        }
    ]
};

return result;

var result =
{
    payload:
        [{
            msgID: msg._msgid,
            counter: msg.counter,
            //time: new Date(msg.metadata.time).getTime(),
        },
        {
            devEUI: msg.hardware_serial,
            devID: msg.dev_id,
            displayName: msg.display_id,
            displayKey: msg.display_key,
            nodeType: msg.local.nodeType,
            platformType: msg.local.platformType,
            radioType: msg.local.radioType,
            applicationName: msg.local.applicationName,
        }]
};

var t = result.payload[0];
var tags = result.payload[1];

// copy the fields we want as values to the database slot 0.
var value_keys = [
    "Vbat", "VDD", "boot", "tDew", "tHeatIndexC", "t", "rh", "irradiance", "lux", "Vbus"
];

// copy the fields we want as tags to the database slot 1
var tag_keys = [
    /* none */
];

function insert_value(pOutput, sInKey, inValue) {
    if (typeof inValue == "object") {
        for (var i in inValue)
            insert_value(pOutput, sInKey + "." + i, inValue[i]);
    }
    else
        pOutput[sInKey] = inValue;
}

for (var i in value_keys) {
    var key = value_keys[i];
    if (key in msg.payload) {
        // if we get an object generate an entry for each
        insert_value(t, key, msg.payload[key]);
    }
}
for (var i in tag_keys) {
    var key_tag = tag_keys[i];
    if (key_tag in msg.payload)
        tags[key_tag] = msg.payload[key_tag];
}

return result;

/*
Name:   ttn_v3_to_v2_convertor.js

Function:
    This function converts the TTN v3 payload into v2 payload format.

Copyright and License:
    This file copyright (c) 2021 by

        MCCI Corporation
        3520 Krums Corners Road
        Ithaca, NY   14850

    An unpublished work. All rights reserved

    This file is proprietary information, and may not be disclosed or
    copied without the prior permission of MCCI Corporation

Author:
    Sivaprakash Veluthambi, MCCI Corporation   March 2021

*/

function fixChannel(msg) {
    var bandwidth = msg.payload_v3.uplink_message.settings.frequency;
    var frequency = msg.payload_v3.uplink_message.settings.data_rate.lora.bandwidth/1000;
    var fBase = bandwidth === 125 ? 902.3 : 903;
    var fWidth = bandwidth === 125 ? 0.2 : 1.6;
    var chBase = bandwidth === 125 ? 0 : 64;
    var channel = (frequency - fBase) / fWidth + chBase;
    // channel is the 0..71 channel from the regional spec,
    // not the number from TTN v2 for US.
    // round channel to nearest multiple of 0.001
    channel = Math.floor(channel * 1000 + 0.5) / 1000;
    if (0 <= channel && channel <= 63 && bandwidth === 125) {
        // probably US. that means subband 2, so offset
        msg.payload.metadata.gateways[i].channel = channel - 8;
    } else if (64 <= channel && channel <= 71 && bandwidth === 500) {
        msg.payload.metadata.gateways[i].channel = channel;
    } else {
        msg.payload.metadata.gateways[i].channel = 0;
    }
}

if (msg.topic.startsWith("v3")) {
    msg['payload_v3'] = msg.payload;
    msg.payload = {};

    // device info
    msg.payload.app_id = msg.payload_v3.end_device_ids.application_ids.application_id;
    msg.payload.dev_id = msg.payload_v3.end_device_ids.device_id;
    msg.payload.hardware_serial = msg.payload_v3.end_device_ids.dev_eui;

    // uplink info
    msg.payload.port = msg.payload_v3.uplink_message.f_port;
    msg.payload.counter = msg.payload_v3.uplink_message.f_cnt;
    msg.payload.payload_raw = msg.payload_v3.uplink_message.frm_payload;

    msg.payload.payload_fields = {};
    msg.payload.payload_fields = msg.payload_v3.uplink_message.decoded_payload;

    // metadata
    msg.payload.metadata = {};
    msg.payload.metadata.time = msg.payload_v3.uplink_message.received_at;
    msg.payload.metadata.frequency = msg.payload_v3.uplink_message.settings.frequency/(1000*1000);
    msg.payload.metadata.modulation = "LORA"
    // data rate = spreading factor + bandwidth
    msg.payload.metadata.data_rate = "SF" + msg.payload_v3.uplink_message.settings.data_rate.lora.spreading_factor + "BW" + (msg.payload_v3.uplink_message.settings.data_rate.lora.bandwidth/1000)
    msg.payload.metadata.airtime = msg.payload_v3.uplink_message.consumed_airtime;
    msg.payload.metadata.coding_rate = msg.payload_v3.uplink_message.settings.data_rate.lora.coding_rate;

    // metadata gateway info
    msg.payload.metadata.gateways = [];
    for (var i in msg.payload_v3.uplink_message.rx_metadata) {
        msg.payload.metadata.gateways[i] = {};
        msg.payload.metadata.gateways[i].gtw_id = msg.payload_v3.uplink_message.rx_metadata[i].gateway_ids.gateway_id;
        msg.payload.metadata.gateways[i].rssi = msg.payload_v3.uplink_message.rx_metadata[i].rssi;
        msg.payload.metadata.gateways[i].snr = msg.payload_v3.uplink_message.rx_metadata[i].snr;
        msg.payload.metadata.gateways[i].rf_chain = "unknown";

        if ("channel_index" in msg.payload_v3.uplink_message.rx_metadata[i] && msg.payload_v3.uplink_message.rx_metadata[i].channel_index > 0) {
            msg.payload.metadata.gateways[i].channel = msg.payload_v3.uplink_message.rx_metadata[i].channel_index;
        }
        else {
            // fix channel
            fixChannel(msg)
        }

        if ("timestamp" in msg.payload_v3.uplink_message.rx_metadata[i]) {
            msg.payload.metadata.gateways[i].timestamp = msg.payload_v3.uplink_message.rx_metadata[i].timestamp;
        }

        if ("time" in msg.payload_v3.uplink_message.rx_metadata[i]) {
            msg.payload.metadata.gateways[i].time = msg.payload_v3.uplink_message.rx_metadata[i].time;
        }
    }

}

return msg;

// move things around.
// since some TTN things are not portable,
// in future we might not want to use them.

var result = {};
var payload = msg.payload;


// save original data
result.network_payload = msg;

// app_id: TTN concept, not portable.
//  query a database to pick this up.
result.app_id = "app-id-" + payload.app_id;

// dev_id: TTN concept, not portable
//  use "device-*" notation, later query a
//  database to pick this up.
result.dev_id = payload.dev_id.startsWith("device-") ? payload.dev_id : "device-" + payload.dev_id;

// hardware_serial: TTN name; we ought to use DevEUI.
result.hardware_serial = payload.hardware_serial;

// port: this is the uplink port.
result.port = parseInt(payload.port);

// counter: this is FCntUp
result.counter = parseInt(payload.counter);

result.payload_raw = payload.payload_raw;
result.payload = payload.payload_raw;

// metadata
var metadata = {};
result.metadata = metadata;
metadata.network = "TTN";
metadata.time = new Date(payload.Time);
// this might be FSK, but..
metadata.modulation = "LORA";
// this might be BW250 but...
metadata.data_rate =  payload.metadata.data_rate;
metadata.coding_rate = payload.metadata.coding_rate;

//  database to pick frequency as actility do not provide.
metadata.frequency = payload.metadata.frequency;
metadata.gateways = [];
metadata.gateways[0] = {};
metadata.gateways[0].gtw_id = payload.metadata.gateways[0].gtw_id;
metadata.gateways[0].rssi = payload.metadata.gateways[0].rssi;
metadata.gateways[0].snr = payload.metadata.gateways[0].snr;
metadata.gateways[0].rf_chain = payload.metadata.gateways[0].rf_chain;
// this is wrong, but looks like data is region-specific
metadata.gateways[0].channel = payload.metadata.gateways[0].channel;
metadata.gateways[0].latitude = payload.metadata.gateways[0].latitude;
metadata.gateways[0].longitude =payload.metadata.gateways[0].longitude;

return result;

// -------------------- SAFETY --------------------
if (!msg.payload || typeof msg.payload !== "object") return null;
if (!msg.payload.data || !msg.payload.txInfo) return null;

var d = msg.payload;

// Force topic to look like TTN
msg.topic = "v3/chirpstack/devices/" + (d.deviceInfo?.deviceName || "unknown") + "/up";

msg.payload = {
    end_device_ids: {
        device_id: d.deviceInfo?.deviceName || "unknown",
        dev_eui: d.deviceInfo?.devEui || "unknown",
        application_ids: {
            application_id: d.deviceInfo?.applicationName || "chirpstack"
        }
    },
    uplink_message: {
        f_port: d.fPort,
        f_cnt: d.fCnt,
        frm_payload: d.data,
        received_at: d.time,

        settings: {
            frequency: d.txInfo.frequency,
            data_rate: {
                lora: {
                    bandwidth: d.txInfo.modulation.lora.bandwidth,
                    spreading_factor: d.txInfo.modulation.lora.spreadingFactor,
                    coding_rate: (d.txInfo.modulation.lora.codeRate || "").replace("CR_", "").replace("_", "/")
                }
            }
        },

        rx_metadata: (d.rxInfo || []).map(gw => ({
            gateway_ids: {
                gateway_id: gw.gatewayId
            },
            rssi: gw.rssi,
            snr: gw.snr,
            channel_index: gw.channel,
            time: gw.gwTime
        }))
    }
};

return msg;

// Build raw-binary ChirpStack Gateway Mesh MeshCommand protobuf messages
// telling every relay listed in RELAY_IDS to set its system clock.
// Add a new relay by adding its Relay ID (hex string, as shown in
// ChirpStack's Gateway Mesh > Relay Gateways list) to RELAY_IDS below -
// no other change needed here.
//
// Verified against chirpstack/api/proto/gw/gw.proto:
//   MeshCommand { gateway_id=1(string), relay_id=2(string), commands=3(repeated MeshCommandItem) }
//   MeshCommandItem { proprietary=1(MeshCommandProprietary) }
//   MeshCommandProprietary { command_type=1(uint32), payload=2(bytes) }
// The command/mesh MQTT topic expects this message RAW (protobuf binary),
// not JSON - the border mqtt-forwarder has no json=true override here.

var BORDER_GATEWAY_ID = "7076ff0064050e55";
var RELAY_IDS = [
    "64050f40"  // Kerlink relay #1
    // "xxxxxxxx", // add additional relays here
];
var COMMAND_TYPE = 129; // matches [commands.commands] entry 129 on each relay, mapped to settime.sh

function varint(n) {
    var bytes = [];
    while (true) {
        var b = n & 0x7F;
        n = n >>> 7;
        if (n) { bytes.push(b | 0x80); } else { bytes.push(b); break; }
    }
    return Buffer.from(bytes);
}
function tag(fieldNum, wireType) { return varint((fieldNum << 3) | wireType); }
function lenDelim(fieldNum, data) { return Buffer.concat([tag(fieldNum, 2), varint(data.length), data]); }
function varintField(fieldNum, value) { return Buffer.concat([tag(fieldNum, 0), varint(value)]); }

// The relay BusyBox date -s needs "YYYY-MM-DD HH:MM:SS" UTC, not ISO-8601
// (ISO-8601 with T/Z/fractional seconds was tested and rejected as an invalid date).
function nowUtcBusyBox() {
    var d = new Date();
    function pad(n) { return (n < 10 ? "0" : "") + n; }
    return d.getUTCFullYear() + "-" + pad(d.getUTCMonth() + 1) + "-" + pad(d.getUTCDate())
        + " " + pad(d.getUTCHours()) + ":" + pad(d.getUTCMinutes()) + ":" + pad(d.getUTCSeconds());
}

function buildMeshCommand(relayId, payload) {
    var proprietary = Buffer.concat([varintField(1, COMMAND_TYPE), lenDelim(2, payload)]);
    var item = lenDelim(1, proprietary);
    return Buffer.concat([
        lenDelim(1, Buffer.from(BORDER_GATEWAY_ID, "ascii")),
        lenDelim(2, Buffer.from(relayId, "ascii")),
        lenDelim(3, item)
    ]);
}

var payload = Buffer.from(nowUtcBusyBox(), "utf8");
var topic = "in865/gateway/" + BORDER_GATEWAY_ID + "/command/mesh";
var outMsgs = RELAY_IDS.map(function (relayId) {
    return { topic: topic, payload: buildMeshCommand(relayId, payload) };
});

return [outMsgs];

// Decode a raw-binary ChirpStack Gateway Mesh MeshEvent protobuf message
// and surface only the settime.sh response (proprietary eventType 129).
// Routine heartbeats and other event types are ignored (return null).
// Schema (chirpstack/api/proto/gw/gw.proto):
//   MeshEvent { gateway_id=1(string), relay_id=2(string), time=3(Timestamp), events=4(repeated MeshEventItem) }
//   MeshEventItem { proprietary=1(MeshEventProprietary) or heartbeat=2(MeshEventHeartbeat) }
//   MeshEventProprietary { event_type=1(uint32), payload=2(bytes) }
//
// Requires this node mqtt-in datatype set to "buffer" (not auto/string), so binary
// protobuf bytes are not mangled before reaching here.

function readVarint(buf, pos) {
    var result = 0, shift = 0, b;
    do {
        b = buf[pos.i++];
        result += (b & 0x7F) * Math.pow(2, shift);
        shift += 7;
    } while (b & 0x80);
    return result;
}

function readField(buf, pos) {
    var tagByte = readVarint(buf, pos);
    var fieldNum = tagByte >>> 3;
    var wireType = tagByte & 0x7;
    var value;
    if (wireType === 0) {
        value = readVarint(buf, pos);
    } else if (wireType === 2) {
        var len = readVarint(buf, pos);
        value = buf.slice(pos.i, pos.i + len);
        pos.i += len;
    } else if (wireType === 1) {
        value = buf.slice(pos.i, pos.i + 8); pos.i += 8;
    } else if (wireType === 5) {
        value = buf.slice(pos.i, pos.i + 4); pos.i += 4;
    } else {
        return null;
    }
    return { fieldNum: fieldNum, value: value };
}

function parseMessage(buf) {
    var pos = { i: 0 };
    var fields = {};
    while (pos.i < buf.length) {
        var f = readField(buf, pos);
        if (!f) break;
        if (!fields[f.fieldNum]) fields[f.fieldNum] = [];
        fields[f.fieldNum].push(f.value);
    }
    return fields;
}

var buf = msg.payload;
if (!Buffer.isBuffer(buf)) {
    node.warn("expected Buffer payload - check mqtt-in node datatype is buffer");
    return null;
}

var top = parseMessage(buf);
var relayId = (top[2] && top[2][0]) ? top[2][0].toString("ascii") : undefined;
var eventsField = top[4] || [];

for (var i = 0; i < eventsField.length; i++) {
    var item = parseMessage(eventsField[i]);
    if (item[1] && item[1][0]) {
        var prop = parseMessage(item[1][0]);
        var eventType = prop[1] ? prop[1][0] : undefined;
        if (eventType === 129) {
            var payloadBuf = prop[2] && prop[2][0];
            var text = payloadBuf ? payloadBuf.toString("utf8") : "";
            msg.payload = { relayId: relayId, settimeOutput: text.trim() };
            return msg;
        }
    }
}
return null;
